Web kamerası izinlerini ve gizlilik ayarlarını test etmek için bir komut dosyası oluşturmak, kullanıcıların cihazlarındaki kamera erişimiyle ilgili bilgileri kontrol etmelerine yardımcı olur. Aşağıda, JavaScript kullanarak bu işlevselliği sağlayan basit bir komut dosyası örneği verilmiştir:

```javascript
// Web Kamerası İzinlerini ve Gizlilik Ayarlarını Test Etme Komut Dosyası

// Kamera erişimi izni isteme ve durumu kontrol etme
async function checkCameraPermissions() {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        console.log("Kamera erişimi izin verildi.");
        stream.getTracks().forEach(track => track.stop());
    } catch (error) {
        if (error.name === 'NotAllowedError') {
            console.log("Kamera erişimi reddedildi. Lütfen izin verin.");
        } else {
            console.error("Kamera erişimi kontrolü sırasında bir hata oluştu:", error);
        }
    }
}

// Gizlilik ayarlarını kontrol etme
function checkPrivacySettings() {
    const privacySettings = {
        // Örnek olarak, tarayıcının gizlilik ayarlarını kontrol etmek için bir işlev
        checkBrowserSettings: () => {
            console.log("Tarayıcı gizlilik ayarları kontrol ediliyor...");
            // Burada tarayıcının gizlilik ayarlarını kontrol eden kodlar yer alabilir, örneğin cookie ayarları, izleme koruması vb.
        }
    };

    privacySettings.checkBrowserSettings();
}

// Komut dosyasını çalıştır
checkCameraPermissions();
checkPrivacySettings();

// Ek işlevler:
// 1. Kamera önizlemesi görüntüleme (isteğe bağlı)
async function displayCameraPreview(stream) {
    const videoElement = document.getElementById('cameraPreview');
    videoElement.srcObject = stream;
}

// 2. Kamera erişimi iptal etme
function stopCamera() {
    const tracks = stream.getTracks();
    tracks.forEach(track => track.stop());
}
```

